async function c(i){return new Promise(o=>{chrome.runtime.sendMessage(i,o)})}document.addEventListener("DOMContentLoaded",async()=>{const i=document.getElementById("login-view"),o=document.getElementById("main-view"),r=document.getElementById("btn-login"),l=document.getElementById("btn-logout"),u=document.getElementById("btn-open-sidebar"),a=document.getElementById("user-email"),n=document.getElementById("status");async function m(){n.textContent="Checking status...";try{const e=await c({action:"GET_TOKEN",interactive:!1});e&&e.token?d(e.token):s()}catch{s()}}function s(){i.classList.remove("hidden"),o.classList.add("hidden"),n.textContent=""}async function d(e){i.classList.add("hidden"),o.classList.remove("hidden"),n.textContent="",a.textContent="User",chrome.identity.getProfileUserInfo(t=>{t.email&&(a.textContent=t.email)})}r.addEventListener("click",async()=>{n.textContent="Signing in...";const e=await c({action:"GET_TOKEN",interactive:!0});e&&e.token?d(e.token):n.textContent="Sign in failed."}),l.addEventListener("click",async()=>{await c({action:"LOGOUT"}),s()}),u.addEventListener("click",()=>{chrome.tabs.query({active:!0,currentWindow:!0},e=>{const t=e[0];t&&t.id&&chrome.scripting.executeScript({target:{tabId:t.id},func:()=>{alert("Sidebar should be active on supported pages.")}})})}),m()});
